INSERT INTO dbo.products (id, sku, name, category, description, price, stock, warranty_months) VALUES
(1,  'LH-TV55-Q7',  'Aurora 55" QLED Smart TV',          'Televisions',  'A 55 inch 4K QLED television with HDR10+, Dolby Vision and a 120Hz panel for smooth sports and gaming. Built-in streaming apps, voice remote and three HDMI 2.1 ports.', 649.00, 34, 24),
(2,  'LH-TV65-OL',  'Aurora 65" OLED Smart TV',          'Televisions',  'Self-lit OLED pixels give perfect blacks and infinite contrast. 65 inch 4K panel, Dolby Atmos sound, auto low latency mode for consoles, and a thin wall-mount design.', 1499.00, 12, 24),
(3,  'LH-TV32-HD',  'Aurora 32" HD Compact TV',          'Televisions',  'Small HD ready television ideal for kitchens, bedrooms and dorm rooms. Low power consumption, built-in DVB-T2 tuner and a USB port for playing your own videos.', 179.00, 80, 12),
(4,  'LH-SB-300',   'Resonance 300 Soundbar',            'Audio',        'A 3.1 channel soundbar with a dedicated centre speaker that makes dialogue in films clearer. Connects to the TV with HDMI ARC or optical, includes Bluetooth music streaming.', 229.00, 45, 12),
(5,  'LH-SB-700',   'Resonance 700 Atmos Soundbar',      'Audio',        'Dolby Atmos soundbar with up-firing drivers and a wireless subwoofer that fills the room with cinema-style surround sound. Supports eARC and room calibration with a microphone.', 599.00, 18, 24),
(6,  'LH-HP-NC1',   'Hush NC1 Wireless Headphones',      'Audio',        'Over-ear Bluetooth headphones with active noise cancellation that blocks engine hum on flights and office chatter. 35 hours of battery, fast charging gives 5 hours in 10 minutes.', 199.00, 60, 12),
(7,  'LH-EB-PRO',   'Hush Pro Earbuds',                  'Audio',        'True wireless earbuds with noise cancelling, transparency mode, IPX5 sweat resistance for workouts and a pocket charging case that adds 24 hours of playback.', 149.00, 120, 12),
(8,  'LH-SPK-GO',   'Pulse Go Portable Speaker',         'Audio',        'Rugged waterproof Bluetooth speaker that floats in the pool and survives drops. 20 hour battery, can pair with a second speaker for stereo at the beach or campsite.', 89.00, 95, 12),
(9,  'LH-LT-14A',   'Vector 14 Ultrabook',               'Computers',    'Lightweight 14 inch laptop weighing 1.2 kg with an aluminium body, 16 GB RAM, 512 GB SSD and an all-day battery. A great choice for students and travelling professionals.', 999.00, 25, 24),
(10, 'LH-LT-16G',   'Vector 16 Gaming Laptop',           'Computers',    'High performance laptop with a dedicated RTX graphics card, 165Hz display, 32 GB RAM and advanced vapour chamber cooling for long gaming sessions and video editing.', 1899.00, 9, 24),
(11, 'LH-DT-MINI',  'Cube Mini Desktop PC',              'Computers',    'Palm-sized desktop computer that mounts behind a monitor. Quiet fan-less design, perfect for home office, spreadsheets and web browsing. Includes Wi-Fi 6 and two display outputs.', 549.00, 30, 12),
(12, 'LH-MON-27Q',  'Clarity 27" QHD Monitor',           'Computers',    '27 inch 1440p IPS monitor with accurate colours for photo editing, a height adjustable stand and USB-C that charges your laptop over a single cable.', 329.00, 40, 36),
(13, 'LH-KB-MX',    'Strike Mechanical Keyboard',        'Accessories',  'Full size mechanical keyboard with hot-swappable switches, per-key RGB lighting and a detachable USB-C cable. Satisfying tactile feel for typing and gaming.', 119.00, 70, 24),
(14, 'LH-MS-ERGO',  'Glide Ergonomic Mouse',             'Accessories',  'Vertical wireless mouse that keeps the wrist in a natural handshake position to reduce strain and pain during long working days. Rechargeable, works on three devices.', 69.00, 85, 12),
(15, 'LH-PB-20K',   'Volt 20000 Power Bank',             'Accessories',  'High capacity 20000 mAh portable charger with 65W USB-C power delivery that can recharge a laptop, phone and tablet while travelling. Airline carry-on approved.', 59.00, 150, 12),
(16, 'LH-CH-3IN1',  'Volt 3-in-1 Wireless Charger',      'Accessories',  'Charging stand that powers a phone, smartwatch and earbuds at the same time on your bedside table. Includes a wall adapter and soft night light mode.', 79.00, 64, 12),
(17, 'LH-PH-X2',    'Nova X2 Smartphone',                'Phones',       'Flagship smartphone with a 6.7 inch AMOLED screen, triple camera with 5x optical zoom for sharp night photos, 256 GB storage and 5 years of security updates.', 899.00, 40, 24),
(18, 'LH-PH-A1',    'Nova A1 Smartphone',                'Phones',       'Affordable smartphone with a large battery that lasts two days, a 50 MP camera and expandable storage. Good first phone for teenagers or as a backup device.', 249.00, 110, 12),
(19, 'LH-TB-10',    'Nova Tab 10',                       'Phones',       '10 inch tablet for reading, video calls and streaming, with stylus support for note taking and a kids mode with parental controls and time limits.', 329.00, 55, 12),
(20, 'LH-WT-FIT',   'Pulse Fit Smartwatch',              'Wearables',    'Fitness smartwatch with GPS, heart rate and blood oxygen tracking, sleep analysis and 50 metre water resistance for swimming. Battery lasts up to 10 days.', 199.00, 75, 12),
(21, 'LH-CAM-IN',   'Sentinel Indoor Camera',            'Smart Home',   'Indoor security camera with 2K video, night vision, two-way talk and person detection that alerts your phone. Privacy shutter closes the lens when you are home.', 49.00, 140, 12),
(22, 'LH-CAM-OUT',  'Sentinel Outdoor Camera',           'Smart Home',   'Weatherproof wire-free outdoor camera with a spotlight, colour night vision and a six month rechargeable battery. Watch your driveway and garden from anywhere.', 129.00, 48, 24),
(23, 'LH-DB-V2',    'Sentinel Video Doorbell',           'Smart Home',   'Video doorbell that lets you see and speak to visitors and delivery drivers from your phone, with package detection and a chime that plugs into any socket.', 99.00, 66, 12),
(24, 'LH-BULB-4',   'Glow Smart Bulbs (4 pack)',         'Smart Home',   'Colour changing Wi-Fi light bulbs that you control by voice or app. Set schedules, dim for movie night and wake up gently with a sunrise routine. No hub required.', 39.00, 200, 24),
(25, 'LH-THERM',    'Climate Smart Thermostat',          'Smart Home',   'Learning thermostat that adjusts the heating to your routine and switches off when nobody is home, cutting energy bills. Works with most boilers and heat pumps.', 179.00, 37, 24),
(26, 'LH-VAC-R5',   'Sweep R5 Robot Vacuum',             'Home Appliances', 'Robot vacuum with laser navigation that maps every room, avoids cables and socks, and empties itself into a base station. Strong suction for pet hair on carpets.', 449.00, 22, 24),
(27, 'LH-AIR-P3',   'Breeze P3 Air Purifier',            'Home Appliances', 'HEPA air purifier that removes pollen, dust and smoke for allergy sufferers. Quiet sleep mode and an air quality sensor that shows a colour ring.', 189.00, 41, 24),
(28, 'LH-KET-SM',   'Brew Smart Kettle',                 'Home Appliances', 'Variable temperature kettle that holds water at the right heat for green tea or coffee, and can be started from your phone before you get out of bed.', 79.00, 58, 12),
(29, 'LH-RTR-AX',   'Mesh AX3000 Wi-Fi System (3 pack)', 'Networking',   'Whole home mesh Wi-Fi 6 that removes dead zones in large or multi-storey houses. Easy app setup, parental controls and a guest network.', 279.00, 33, 24),
(30, 'LH-EXT-AC',   'Mesh Range Extender',               'Networking',   'Plug-in Wi-Fi extender that boosts a weak signal in the garden, garage or upstairs bedroom. One button pairing with any router.', 45.00, 90, 12);
GO

INSERT INTO dbo.articles (id, title, category, body, tags) VALUES
(1,  'How to return an item for a refund', 'Returns & Refunds',
 'You can send back most products within 30 days of delivery if they are unused and in the original packaging. Start a return from the Orders page, print the prepaid label and drop the parcel at any post office. Refunds go back to the original payment method within 5 to 7 business days after the warehouse inspects the item. Opened headphones and earbuds can only be returned if faulty, for hygiene reasons.',
 'return,refund,money back,30 days'),
(2,  'My order has not arrived yet', 'Shipping & Delivery',
 'Standard delivery normally takes 3 to 5 working days. If your parcel is late, first check the tracking link in your dispatch email, because couriers sometimes leave items with a neighbour or in a safe place. If tracking has not updated for more than 3 days, or it says delivered but you cannot find it, contact support and we will open an investigation with the courier and send a replacement or refund.',
 'late delivery,missing parcel,tracking,courier'),
(3,  'Delivery options and costs', 'Shipping & Delivery',
 'Orders over 50 dollars ship free with standard delivery. Express next-day delivery costs 9.99 when ordered before 2pm on a weekday. Large items such as televisions over 55 inches are delivered by a two-person team who can also take away your old TV for recycling.',
 'shipping cost,express,next day,free shipping'),
(4,  'Changing or cancelling an order', 'Orders',
 'Orders can be changed or cancelled free of charge until they are packed, usually within one hour of purchase. Go to Orders, select the order and choose Cancel. If the order has already shipped, you can refuse the delivery or return it using the normal returns process.',
 'cancel,change order,modify'),
(5,  'Warranty coverage explained', 'Warranty & Repairs',
 'Every product includes a manufacturer warranty of at least 12 months, and many televisions and computers include 24 or 36 months. The warranty covers manufacturing defects and hardware failures under normal use. It does not cover accidental damage such as cracked screens, liquid spills or drops. You can check how long your warranty lasts on the product page or in your order history.',
 'warranty,guarantee,defect,coverage'),
(6,  'How to make a warranty claim', 'Warranty & Repairs',
 'If a device stops working within its warranty period, open a repair request from the Support page with your order number and a short description or video of the fault. We will email a free shipping label. Most repairs are completed within 10 working days; if a repair is not possible we replace the product.',
 'repair,broken,claim,faulty'),
(7,  'TV has sound but no picture', 'Troubleshooting',
 'If your television plays audio but the screen stays black, first press the Home button on the remote to check whether the screen is simply turned off by the energy saving mode. Then unplug the TV from the wall for 60 seconds to perform a power cycle. Check that the HDMI cable is firmly seated and try a different HDMI port. If the backlight still does not turn on, the panel may need repair under warranty.',
 'black screen,no picture,display,television'),
(8,  'Fixing Bluetooth pairing problems', 'Troubleshooting',
 'When headphones, earbuds or speakers will not connect, remove the device from your phone Bluetooth list and forget it, then put the accessory back into pairing mode by holding the power button for 7 seconds until the light flashes blue. Keep the devices within one metre, make sure the battery is charged, and turn off Bluetooth on other nearby phones or laptops that might grab the connection first.',
 'bluetooth,pairing,connect,headphones,wireless'),
(9,  'Wi-Fi keeps dropping or is slow', 'Troubleshooting',
 'Unstable internet is usually caused by distance or interference. Move the router to a central, raised position away from microwaves and thick walls, restart it, and update its firmware in the app. Large homes may need a mesh system or range extender to cover every room. If only one device is affected, forget the network on that device and reconnect.',
 'wifi,internet,slow,disconnect,router,signal'),
(10, 'Laptop battery drains quickly', 'Troubleshooting',
 'To get more hours from a charge, lower the screen brightness, close apps running in the background and switch Windows to the Best power efficiency mode. Check Settings > System > Power & battery to see which apps use the most energy. Batteries naturally lose capacity after a few hundred charge cycles; if capacity is below 80 percent within the warranty period we will replace it.',
 'battery life,power,laptop,charging'),
(11, 'Phone overheating when charging', 'Troubleshooting',
 'It is normal for a phone to get warm during fast charging, but it should never be too hot to hold. Remove thick cases while charging, avoid charging in direct sunlight or under a pillow, and use the original charger and cable. If the phone shows a temperature warning or the battery swells, stop using it and contact support immediately.',
 'hot,heat,temperature,charging,phone'),
(12, 'Resetting a forgotten account password', 'Account & Security',
 'On the sign in page choose Forgot password and enter your email address. We will send a reset link that is valid for 30 minutes. If the email does not arrive, check your spam or junk folder. For security, support staff can never see or tell you your current password.',
 'password,login,sign in,reset,locked out'),
(13, 'Turning on two-factor authentication', 'Account & Security',
 'Protect your account with a second step at sign in. Open Account settings > Security and choose Two-factor authentication, then scan the QR code with an authenticator app. Save the backup codes somewhere safe so you can still get in if you lose your phone.',
 '2fa,security,authenticator,mfa'),
(14, 'Updating your delivery address', 'Account & Security',
 'You can store several addresses in Account settings > Addresses and choose a default. To change the address of an order that has not shipped, cancel and re-place it, or contact support within one hour of ordering.',
 'address,profile,shipping address'),
(15, 'Accepted payment methods', 'Payments & Billing',
 'We accept Visa, Mastercard, American Express, PayPal, Apple Pay and Google Pay. Payment is taken when your order is dispatched. Gift cards can be combined with another payment method at checkout.',
 'payment,credit card,paypal,checkout'),
(16, 'Pay in instalments', 'Payments & Billing',
 'Orders over 300 dollars can be split into 12 interest-free monthly payments, subject to a credit check. Choose Pay monthly at checkout. Missed payments may incur a late fee, and you can settle the remaining balance early at any time with no penalty.',
 'finance,instalments,monthly payments,credit'),
(17, 'I was charged twice', 'Payments & Billing',
 'Sometimes your bank shows a temporary authorisation hold as well as the final payment. Holds disappear automatically within 3 to 5 days. If two completed charges appear on your statement for the same order, send us a screenshot and we will refund the duplicate payment.',
 'double charge,duplicate payment,billing error'),
(18, 'Price match promise', 'Payments & Billing',
 'If you find the same product cheaper at a major retailer within 14 days of buying it, we will refund the difference. The item must be new, in stock and sold by the retailer itself, not a marketplace seller.',
 'price match,cheaper,discount'),
(19, 'Setting up your smart home camera', 'Smart Home',
 'Download the Lumen Home app, tap Add device and scan the QR code on the camera. Connect it to a 2.4 GHz Wi-Fi network, because 5 GHz is not supported by the camera. Choose a mounting spot with a clear view and use the app to set activity zones so you are only notified about the doorway or driveway.',
 'camera setup,install,security camera,wifi'),
(20, 'Keeping your recordings private', 'Smart Home',
 'Video from Sentinel cameras is encrypted end to end and stored for 30 days. You can turn on privacy mode to stop recording automatically when your phone is at home, and delete clips at any time. We never share your footage with third parties.',
 'privacy,encryption,recordings,data'),
(21, 'Robot vacuum gets stuck', 'Troubleshooting',
 'If the vacuum keeps stopping, clear cables, rug tassels and small objects from the floor, clean the cliff sensors and wheels with a dry cloth, and remove hair wrapped around the brush roll. Use no-go zones in the app to block areas under low furniture.',
 'robot vacuum,stuck,cleaning,maintenance'),
(22, 'Recycling your old electronics', 'Sustainability',
 'We take back old phones, laptops, cables and batteries for free, whether you bought them from us or not. Drop them at a store collection point or request a free recycling bag. Wipe your personal data first by doing a factory reset.',
 'recycle,e-waste,environment,trade in'),
(23, 'Trade in your old phone', 'Sustainability',
 'Get credit towards a new device by trading in your old smartphone or tablet. Answer a few questions about its condition to get an instant quote, send it in with the free label, and receive store credit within 5 days of it arriving.',
 'trade in,credit,old phone,upgrade'),
(24, 'Student discount', 'Promotions',
 'Students in college or university get 10 percent off laptops, tablets and headphones. Verify your status once with your school email address and the discount applies automatically at checkout for 12 months.',
 'student,discount,education,university'),
(25, 'Gift cards', 'Promotions',
 'Digital gift cards are delivered by email within minutes and never expire. They can be used online and in store, but cannot be exchanged for cash. Check your balance on the Gift cards page.',
 'gift card,voucher,present'),
(26, 'Contacting customer support', 'Support',
 'Our support team is available by live chat and phone from 8am to 8pm, seven days a week. Have your order number ready. Average waiting time on live chat is under 2 minutes; email replies are sent within 24 hours.',
 'contact,help,phone number,chat,opening hours'),
(27, 'Error E-104 on smart thermostat', 'Troubleshooting',
 'Error code E-104 means the thermostat has lost communication with the boiler receiver. Check that the receiver has power and its light is green, then move the thermostat closer or replace its batteries. Re-pair them by holding both buttons for 10 seconds.',
 'e-104,thermostat,error code,heating'),
(28, 'Protection plans', 'Warranty & Repairs',
 'An optional protection plan extends cover to 3 years and adds accidental damage such as drops, spills and cracked screens. Plans can be added up to 30 days after purchase and cancelled at any time for a pro-rata refund.',
 'insurance,accidental damage,extended warranty'),
(29, 'Wall mounting a television', 'Installation',
 'Check the VESA pattern on the back of your TV and choose a bracket rated for its weight. Mount onto solid brick or wooden studs, never plasterboard alone. Our installation service can mount the TV, hide cables and set up channels for a fixed fee.',
 'wall mount,bracket,install,vesa'),
(30, 'Parental controls on tablets', 'Smart Home',
 'Turn on Kids mode on Nova tablets to give children their own profile with approved apps only. Set daily screen time limits, bedtime schedules and require a PIN for purchases so there are no surprise app store bills.',
 'kids,children,screen time,parental controls');
GO
